package io.github.veganismftw.templeehptracker;

import com.google.gson.Gson;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class EhpCalculatorTest
{
	private EhpCalculator calculator;

	@Before
	public void setUp()
	{
		calculator = new EhpCalculator(new TempleRateRepository(new Gson()));
	}

	@Test
	public void customRateIsConstant()
	{
		assertEquals(0.5, calculator.calculate(TempleGameMode.MAIN, Skill.AGILITY,
			1_000_000, 1_050_000, 100_000), 1e-9);
	}

	@Test
	public void integratesAcrossTempleBreakpoints()
	{
		double expected = 75_127D / 15_100D + (100_000D - 75_127D) / 35_000D;
		assertEquals(expected, calculator.calculate(TempleGameMode.MAIN, Skill.AGILITY,
			0, 100_000, 0), 1e-9);
	}

	@Test
	public void integratesTempleInterpolatedRates()
	{
		double slope = (46_592D - 29_200D) / 14_612D;
		double expected = Math.log(46_592D / 29_200D) / slope;
		assertEquals(expected, calculator.calculate(TempleGameMode.MAIN, Skill.FISHING,
			0, 14_612, 0), 1e-9);
	}

	@Test
	public void ignoresTempleZeroTimeRows()
	{
		assertEquals(0, calculator.calculate(TempleGameMode.MAIN, Skill.ATTACK,
			0, 100_000, 0), 1e-9);
		assertFalse(calculator.getRateAt(TempleGameMode.MAIN, Skill.ATTACK, 10_000, 0).isDirect());
	}

	@Test
	public void reportsPublishedAndMissingRates()
	{
		assertTrue(calculator.getRateAt(TempleGameMode.MAIN, Skill.AGILITY, 100_000, 0).isDirect());
		assertFalse(calculator.getRateAt(TempleGameMode.MAIN, Skill.MAGIC, 100_000, 0).isDirect());
	}

	@Test
	public void selectsFletchingRateFromCurrentXpBracket()
	{
		assertEquals(1_524_300,
			calculator.getRateAt(TempleGameMode.IRON, Skill.FLETCHING, 0, 0).getRate(), 0);
		assertEquals(300_000,
			calculator.getRateAt(TempleGameMode.ULTIMATE_IRON, Skill.FLETCHING, 0, 0).getRate(), 0);
		assertEquals(300_000,
			calculator.getRateAt(TempleGameMode.ULTIMATE_IRON, Skill.FLETCHING, 123_659, 0).getRate(), 0);
		assertEquals(880_000,
			calculator.getRateAt(TempleGameMode.ULTIMATE_IRON, Skill.FLETCHING, 123_660, 0).getRate(), 0);
		assertEquals(980_000,
			calculator.getRateAt(TempleGameMode.ULTIMATE_IRON, Skill.FLETCHING, 13_034_431, 0).getRate(), 0);
	}

	@Test
	public void calculatesEhpLeftToTheNextLevelFromExactXp()
	{
		int currentXp = 123_660;
		EhpSkillGoal goal = EhpSkillGoal.forXp(currentXp);
		double expected = (goal.getEndXp() - currentXp) / 880_000D;
		assertEquals(expected, calculator.calculate(
			TempleGameMode.ULTIMATE_IRON,
			Skill.FLETCHING,
			currentXp,
			goal.getEndXp(),
			0), 1e-9);
	}
}

