package io.github.veganismftw.templeehptracker;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class PluginIconTest
{
	@Test
	public void iconKeepsNativeRuneLiteStatBarSize() throws IOException
	{
		try (InputStream stream = getClass().getResourceAsStream("/temple-ehp-icon.png"))
		{
			assertNotNull(stream);
			BufferedImage icon = ImageIO.read(stream);
			assertNotNull(icon);
			assertEquals(23, icon.getWidth());
			assertEquals(22, icon.getHeight());

			int goldPixels = 0;
			int minX = icon.getWidth();
			int maxX = -1;
			int minY = icon.getHeight();
			int maxY = -1;
			for (int y = 0; y < icon.getHeight(); y++)
			{
				for (int x = 0; x < icon.getWidth(); x++)
				{
					int color = icon.getRGB(x, y);
					int red = color >>> 16 & 0xFF;
					int green = color >>> 8 & 0xFF;
					int blue = color & 0xFF;
					if (red >= 220 && green >= 140 && blue <= 120)
					{
						goldPixels++;
						minX = Math.min(minX, x);
						maxX = Math.max(maxX, x);
						minY = Math.min(minY, y);
						maxY = Math.max(maxY, y);
					}
				}
			}
			assertTrue("Hourglass needs enough high-contrast gold pixels", goldPixels >= 20);
			assertTrue("Hourglass needs to span most of the lower-right corner", maxX - minX >= 8);
			assertTrue("Hourglass needs to remain tall enough to read at native size", maxY - minY >= 9);
		}
	}
}

package io.github.veganismftw.templeehptracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class UiFormatTest
{
	@Test
	public void ehpValuesAlwaysUseTwoDecimalPlaces()
	{
		assertEquals("0.00", UiFormat.ehp(0));
		assertEquals("1.23", UiFormat.ehp(1.234));
		assertEquals("12.35", UiFormat.ehpRate(12.3451));
	}

	@Test
	public void playedTimeUsesDaysAfterTwentyFourHours()
	{
		assertEquals("23h 05m", UiFormat.playedTime(23 * 60 + 5));
		assertEquals("1d 0h 00m", UiFormat.playedTime(24 * 60));
		assertEquals("10d 2h 14m", UiFormat.playedTime(10 * 24 * 60 + 2 * 60 + 14));
	}

	@Test
	public void goalTimeMatchesXpTrackerStyle()
	{
		assertEquals("∞", UiFormat.timeTillGoal(1_000, 0));
		assertEquals("0:30:00", UiFormat.timeTillGoal(500, 1_000));
		assertEquals("9:22:21", UiFormat.timeTillGoal(33_741, 3_600));
		assertEquals("26:00:00", UiFormat.timeTillGoal(26_000, 1_000));
	}
}

package io.github.veganismftw.templeehptracker;

import java.lang.reflect.Constructor;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class CanvasMetricOverallTest
{
	@Test
	public void overallMetricsUseCumulativeSessionValues() throws Exception
	{
		EhpSession.SessionView view = sessionView();
		assertEquals("0.25", CanvasMetric.EHP_GAINED.format(view));
		assertEquals("0.50", CanvasMetric.EHP_PER_HOUR.format(view));
		assertEquals("0.00", CanvasMetric.EHP_LEFT.format(view));
		assertEquals("1,000", CanvasMetric.XP_GAINED.format(view));
		assertEquals("2,000", CanvasMetric.XP_PER_HOUR.format(view));
		assertEquals("0", CanvasMetric.XP_LEFT.format(view));
	}

	@Test
	public void emptyOverallProgressIsSafe() throws Exception
	{
		OverallCanvasProgress progress = OverallCanvasProgress.from(sessionView());
		assertEquals(0, progress.getTotalLevel());
		assertEquals(0, progress.getMaximumTotalLevel());
		assertEquals(0, progress.getProgress(), 0);
	}

	private static EhpSession.SessionView sessionView() throws Exception
	{
		Constructor<EhpSession.SessionView> constructor = EhpSession.SessionView.class
			.getDeclaredConstructor(boolean.class, java.util.List.class, double.class,
				double.class, int.class, double.class, long.class);
		constructor.setAccessible(true);
		return constructor.newInstance(
			true, Collections.emptyList(), 0.25, 0.50, 1_000, 2_000D, 60_000L);
	}
}

package io.github.veganismftw.templeehptracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.api.GameState;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TempleEhpPluginTest
{
	@Test
	public void worldHopsAreNotTreatedAsLogouts()
	{
		assertTrue(TempleEhpPlugin.isLoggedInForTracking(GameState.HOPPING));
		assertTrue(TempleEhpPlugin.isLoggedInForTracking(GameState.LOADING));
		assertTrue(TempleEhpPlugin.isLoggedInForTracking(GameState.LOGGED_IN));
		assertTrue(TempleEhpPlugin.isLoggedInForTracking(GameState.CONNECTION_LOST));
	}

	@Test
	public void loginStatesAreTreatedAsLoggedOut()
	{
		assertFalse(TempleEhpPlugin.isLoggedInForTracking(GameState.LOGIN_SCREEN));
		assertFalse(TempleEhpPlugin.isLoggedInForTracking(GameState.LOGIN_SCREEN_AUTHENTICATOR));
		assertFalse(TempleEhpPlugin.isLoggedInForTracking(GameState.LOGGING_IN));
	}

	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TempleEhpPlugin.class);
		RuneLite.main(args);
	}
}

