package io.github.veganismftw.templeehptracker;

import com.google.gson.Gson;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TempleRateRepositoryTest
{
	@Test
	public void bundledSnapshotContainsEveryTempleMode()
	{
		TempleRateRepository repository = new TempleRateRepository(new Gson());
		for (TempleGameMode mode : TempleGameMode.values())
		{
			assertFalse(repository.getLastUpdated(mode).isEmpty());
			assertFalse(repository.getLastUpdated(mode).equals("Unknown"));
		}
	}

	@Test
	public void snapshotIncludesSailingWhereTemplePublishesIt()
	{
		TempleRateRepository repository = new TempleRateRepository(new Gson());
		assertTrue(repository.getRates(TempleGameMode.MAIN, Skill.SAILING).isPresent());
		assertTrue(repository.getRates(TempleGameMode.IRON, Skill.SAILING).isPresent());
		assertFalse(repository.getRates(TempleGameMode.F2P, Skill.SAILING).isPresent());
	}

	@Test
	public void everyPublishedSkillHasALevelOneRate()
	{
		TempleRateRepository repository = new TempleRateRepository(new Gson());
		for (TempleGameMode mode : TempleGameMode.values())
		{
			for (Skill skill : Skill.values())
			{
				repository.getRates(mode, skill).ifPresent(rates ->
				{
					assertFalse(mode + " " + skill + " has no rate rows", rates.getRows().isEmpty());
					assertEquals(mode + " " + skill + " has no level-one rate",
						0, rates.getRows().get(0).getXp());
				});
			}
		}
	}
}

package io.github.veganismftw.templeehptracker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CanvasOverlayLayoutTest
{
	@Test
	public void removingIconShrinksOverlayByIconAndGap()
	{
		BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			int withoutIcon = CanvasOverlayLayout.preferredWidth(
				graphics, 0, 0, "EHP gained", "12.34", "EHP/h", "0.56");
			int withIcon = CanvasOverlayLayout.preferredWidth(
				graphics, 21, 0, "EHP gained", "12.34", "EHP/h", "0.56");
			assertEquals(25, withIcon - withoutIcon);
			assertTrue(withoutIcon < withIcon);
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void progressBarMinimumIsRespected()
	{
		BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			int width = CanvasOverlayLayout.preferredWidth(
				graphics, 0, CanvasOverlayLayout.PROGRESS_BAR_MINIMUM_WIDTH, "XP/h", "1");
			assertTrue(width >= CanvasOverlayLayout.PROGRESS_BAR_MINIMUM_WIDTH);
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void manuallySizedOverlayAlsoShrinksWhenIconIsHidden()
	{
		Dimension hidden = CanvasOverlayLayout.resizeUserWidth(
			new Dimension(140, 70), 125, 100);
		assertEquals(new Dimension(115, 70), hidden);
		Dimension shownAgain = CanvasOverlayLayout.resizeUserWidth(hidden, 100, 125);
		assertEquals(new Dimension(140, 70), shownAgain);
	}

	@Test
	public void removingSecondaryRowPreservesOnlyTheUsersExtraWidth()
	{
		Dimension compact = CanvasOverlayLayout.resizeUserWidth(
			new Dimension(150, 50), 130, 90);
		assertEquals(new Dimension(110, 50), compact);
	}
}

package io.github.veganismftw.templeehptracker;

import java.util.EnumSet;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TempleEhpConfigTest
{
	private final TempleEhpConfig config = new TempleEhpConfig()
	{
	};

	@Test
	public void canvasDefaultsMatchXpTrackerStyleLayout()
	{
		assertEquals(CanvasMetric.EHP_GAINED, config.canvasPrimaryMetric());
		assertEquals(CanvasSecondaryMetric.EHP_PER_HOUR, config.canvasSecondaryMeasurement());
		assertTrue(config.showCanvasSkillIcon());
		assertTrue(config.showCanvasProgressBar());
		assertTrue(config.showCanvasActiveTime());
	}

	@Test
	public void canvasSelectorsExposeSixPrimaryAndSevenSecondaryChoices()
	{
		assertEquals(6, CanvasMetric.values().length);
		assertEquals(7, CanvasSecondaryMetric.values().length);
		assertNull(CanvasSecondaryMetric.NONE.getMetric());
		EnumSet<CanvasMetric> mappedMetrics = EnumSet.noneOf(CanvasMetric.class);
		for (CanvasSecondaryMetric metric : CanvasSecondaryMetric.values())
		{
			if (metric.getMetric() != null)
			{
				mappedMetrics.add(metric.getMetric());
			}
		}
		assertEquals(EnumSet.allOf(CanvasMetric.class), mappedMetrics);
	}

	@Test
	public void secondarySelectorUsesFreshCompatibleConfigKey() throws Exception
	{
		ConfigItem item = TempleEhpConfig.class
			.getMethod("canvasSecondaryMeasurement")
			.getAnnotation(ConfigItem.class);
		assertEquals("canvasSecondaryMeasurement", item.keyName());
	}

	@Test
	public void sidebarSkillActiveTimeIsHiddenByDefault()
	{
		assertFalse(config.showSidebarActiveTime());
	}

	@Test
	public void lifetimeSummaryIsOptIn()
	{
		assertFalse(config.showLifetimeSummary());
	}
}

