package io.github.veganismftw.templeehptracker;

import java.lang.reflect.Field;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class EhpSessionPauseTest
{
	@Test
	public void logoutTransitionIsDeduplicatedAndResumesOnLogin() throws Exception
	{
		EhpSession session = new EhpSession(null, null);
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.ATTACK, 1_000);
		session.initialize(xp);
		session.update(Skill.ATTACK, 1_100, 10_000);

		// Match XP Tracker's once-per-second login-state transition handling.
		session.tickLogout(true, true, 15_000, -1);
		session.tickLogout(true, false, 30_000, -1);
		session.tickLogout(true, false, 60_000, -1);
		session.tickLogout(true, true, 100_000, -1);

		SkillSession attack = skillSession(session, Skill.ATTACK);
		assertEquals(50_000, attack.getActiveMillis(130_000, -1));
		assertTrue(attack.isActive());
	}

	@Test
	public void continuouslyLoggedInStateIncludesWorldHopTime() throws Exception
	{
		EhpSession session = new EhpSession(null, null);
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.ATTACK, 1_000);
		session.initialize(xp);
		session.update(Skill.ATTACK, 1_100, 10_000);

		session.tickLogout(true, true, 15_000, -1);
		session.tickLogout(true, true, 30_000, -1);
		session.tickLogout(true, true, 60_000, -1);

		SkillSession attack = skillSession(session, Skill.ATTACK);
		assertEquals(50_000, attack.getActiveMillis(60_000, -1));
		assertTrue(attack.isActive());
	}

	@SuppressWarnings("unchecked")
	private static SkillSession skillSession(EhpSession session, Skill skill) throws Exception
	{
		Field sessionsField = EhpSession.class.getDeclaredField("sessions");
		sessionsField.setAccessible(true);
		return ((Map<Skill, SkillSession>) sessionsField.get(session)).get(skill);
	}
}

package io.github.veganismftw.templeehptracker;

import com.google.gson.Gson;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LifetimeEhpCalculatorTest
{
	private EhpCalculator ehpCalculator;
	private LifetimeEhpCalculator lifetimeCalculator;

	@Before
	public void setUp()
	{
		ehpCalculator = new EhpCalculator(new TempleRateRepository(new Gson()));
		lifetimeCalculator = new LifetimeEhpCalculator(ehpCalculator);
	}

	@Test
	public void calculatesEstimateLocallyFromBundledRates()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.AGILITY, 100_000);
		xp.put(Skill.COOKING, 37_224);
		double expected = ehpCalculator.calculate(
			TempleGameMode.MAIN, Skill.AGILITY, 0, 100_000, 0)
			+ ehpCalculator.calculate(
				TempleGameMode.MAIN, Skill.COOKING, 0, 37_224, 0);

		LifetimeEhpCalculator.LifetimeView view = lifetimeCalculator.calculate(
			TempleGameMode.MAIN, xp, 600, true);
		assertEquals(expected, view.getEstimatedEhp(), 1e-9);
	}

	@Test
	public void calculatesEfficiencyAsEhpPerPlayedHourPercent()
	{
		assertEquals(25, LifetimeEhpCalculator.efficiencyPercent(50, 12_000), 1e-9);
	}

	@Test
	public void distinguishesUnavailablePlaytimeFromZeroEfficiency()
	{
		LifetimeEhpCalculator.LifetimeView unavailable = lifetimeCalculator.calculate(
			TempleGameMode.MAIN, new EnumMap<>(Skill.class), 0, false);
		assertFalse(unavailable.isPlaytimeAvailable());

		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.AGILITY, 100_000);
		LifetimeEhpCalculator.LifetimeView available = lifetimeCalculator.calculate(
			TempleGameMode.MAIN, xp, 60, true);
		assertTrue(available.isPlaytimeAvailable());
	}
}

package io.github.veganismftw.templeehptracker;

import net.runelite.client.events.ConfigChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CanvasOverlaySettingsTest
{
	@Test
	public void secondarySelectionIsAppliedDirectlyFromConfigEvent()
	{
		CanvasOverlaySettings settings = new CanvasOverlaySettings();
		ConfigChanged event = change(
			TempleEhpConfig.CANVAS_SECONDARY_KEY, CanvasSecondaryMetric.EHP_LEFT.name());

		assertTrue(settings.apply(event));
		assertEquals(CanvasSecondaryMetric.EHP_LEFT, settings.getSecondary());
	}

	@Test
	public void noneAndCompactTogglesAreAppliedWithoutWaitingForSessionRefresh()
	{
		CanvasOverlaySettings settings = new CanvasOverlaySettings();
		assertTrue(settings.apply(change(
			TempleEhpConfig.CANVAS_SECONDARY_KEY, CanvasSecondaryMetric.NONE.name())));
		assertTrue(settings.apply(change(TempleEhpConfig.CANVAS_ICON_KEY, "false")));
		assertTrue(settings.apply(change(TempleEhpConfig.CANVAS_PROGRESS_KEY, "false")));

		assertEquals(CanvasSecondaryMetric.NONE, settings.getSecondary());
		assertFalse(settings.isShowIcon());
		assertFalse(settings.isShowProgress());
	}

	private static ConfigChanged change(String key, String value)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(TempleEhpConfig.GROUP);
		event.setKey(key);
		event.setNewValue(value);
		return event;
	}
}

package io.github.veganismftw.templeehptracker;

import net.runelite.api.Experience;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class EhpSkillGoalTest
{
	@Test
	public void levelOneUsesLevelTwoAsTheGoal()
	{
		EhpSkillGoal goal = EhpSkillGoal.forXp(0);
		assertEquals(1, goal.getStartLevel());
		assertEquals(2, goal.getEndLevel());
		assertEquals(Experience.getXpForLevel(2), goal.getEndXp());
		assertEquals(0, goal.getProgress(), 0);
		assertFalse(goal.isMaxGoal());
	}

	@Test
	public void calculatesProgressInsideTheCurrentLevel()
	{
		int start = Experience.getXpForLevel(27);
		int end = Experience.getXpForLevel(28);
		int xp = start + (end - start) / 2;
		EhpSkillGoal goal = EhpSkillGoal.forXp(xp);
		assertEquals(27, goal.getStartLevel());
		assertEquals(28, goal.getEndLevel());
		assertEquals(50, goal.getProgress(), 0.1);
	}

	@Test
	public void twoHundredMillionIsACompletedGoal()
	{
		EhpSkillGoal goal = EhpSkillGoal.forXp(Experience.MAX_SKILL_XP);
		assertEquals(Experience.MAX_VIRT_LEVEL, goal.getStartLevel());
		assertEquals(Experience.MAX_SKILL_XP, goal.getEndXp());
		assertEquals(100, goal.getProgress(), 0);
		assertTrue(goal.isMaxGoal());
	}
}

package io.github.veganismftw.templeehptracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SkillSessionTest
{
	@Test
	public void pausesAtTheConfiguredIdleBoundary()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);
		session.update(1_200, 20_000);
		session.applyIdlePause(90_000, 60_000);

		assertEquals(70_000, session.getActiveMillis(90_000, 60_000));
		assertEquals(200, session.getXpGained());
		assertFalse(session.isActive());
	}

	@Test
	public void excludesXpGainedDuringLogout()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);
		session.pauseForLogout(20_000, 60_000);
		session.reconcile(1_500);

		assertEquals(100, session.getXpGained());
		assertEquals(1_500, session.getCurrentXp());
	}

	@Test
	public void disabledAutoPauseKeepsTimerRunning()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);
		session.applyIdlePause(3_610_000, -1);

		assertEquals(3_600_000, session.getActiveMillis(3_610_000, -1));
		assertTrue(session.isActive());
	}

	@Test
	public void reconciliationAcrossWorldHopKeepsTimerRunning()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);

		// The post-hop XP synchronization must not pause or reset the timer.
		session.reconcile(1_100);
		session.update(1_200, 40_000);

		assertEquals(30_000, session.getActiveMillis(40_000, 60_000));
		assertEquals(200, session.getXpGained());
		assertTrue(session.isActive());
	}

	@Test
	public void resumesLogoutPauseImmediatelyAfterLogin()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);
		session.pauseForLogout(20_000, -1);
		session.resumeAfterLogin(100_000, -1);

		assertEquals(40_000, session.getActiveMillis(130_000, -1));
		assertEquals(100, session.getXpGained());
		assertTrue(session.isActive());
	}

	@Test
	public void loginDoesNotClearAnExpiredIdlePause()
	{
		SkillSession session = new SkillSession();
		session.initialize(1_000);
		session.update(1_100, 10_000);
		session.pauseForLogout(20_000, 60_000);
		session.resumeAfterLogin(80_000, 60_000);

		assertEquals(10_000, session.getActiveMillis(100_000, 60_000));
		assertFalse(session.isActive());
	}
}

package io.github.veganismftw.templeehptracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
final class EhpSession
{
	private final Map<Skill, SkillSession> sessions = new EnumMap<>(Skill.class);
	private final EhpCalculator calculator;
	private final CustomRateStore customRateStore;
	private long overallAccumulatedMillis;
	private long overallActiveSince;
	private long overallLastGainAt;
	private boolean overallActive;
	private boolean overallPausedForLogout;
	private boolean previouslyLoggedIn;
	private boolean initialized;

	@Inject
	EhpSession(EhpCalculator calculator, CustomRateStore customRateStore)
	{
		this.calculator = calculator;
		this.customRateStore = customRateStore;
		for (Skill skill : Skill.values())
		{
			sessions.put(skill, new SkillSession());
		}
	}

	synchronized void initialize(Map<Skill, Integer> currentXp)
	{
		for (Skill skill : Skill.values())
		{
			sessions.get(skill).initialize(currentXp.getOrDefault(skill, 0));
		}
		overallAccumulatedMillis = 0;
		overallActiveSince = 0;
		overallLastGainAt = 0;
		overallActive = false;
		overallPausedForLogout = false;
		initialized = true;
	}

	synchronized void reset(Map<Skill, Integer> currentXp)
	{
		initialize(currentXp);
	}

	synchronized void reconcile(Map<Skill, Integer> currentXp)
	{
		if (!initialized)
		{
			initialize(currentXp);
			return;
		}
		for (Skill skill : Skill.values())
		{
			sessions.get(skill).reconcile(currentXp.getOrDefault(skill, 0));
		}
	}

	synchronized void update(Skill skill, int xp, long now)
	{
		if (!initialized || skill == null)
		{
			return;
		}
		if (sessions.get(skill).update(xp, now))
		{
			if (!overallActive)
			{
				overallActive = true;
				overallActiveSince = now;
			}
			overallLastGainAt = now;
		}
	}

	synchronized void tick(long now, long pauseAfterMillis)
	{
		if (!initialized)
		{
			return;
		}
		for (SkillSession session : sessions.values())
		{
			session.applyIdlePause(now, pauseAfterMillis);
		}
		if (pauseAfterMillis >= 0 && overallActive && now - overallLastGainAt >= pauseAfterMillis)
		{
			long pauseAt = overallLastGainAt + pauseAfterMillis;
			overallAccumulatedMillis += Math.max(0, pauseAt - overallActiveSince);
			overallActive = false;
		}
	}

	synchronized void tickLogout(boolean pauseOnLogout, boolean loggedIn, long now,
		long pauseAfterMillis)
	{
		if (!previouslyLoggedIn && loggedIn)
		{
			previouslyLoggedIn = true;
			resumeAfterLogin(now, pauseAfterMillis);
		}
		else if (previouslyLoggedIn && !loggedIn)
		{
			previouslyLoggedIn = false;
			if (pauseOnLogout)
			{
				pauseForLogout(now, pauseAfterMillis);
			}
		}
	}

	private void pauseForLogout(long now, long pauseAfterMillis)
	{
		for (SkillSession session : sessions.values())
		{
			session.pauseForLogout(now, pauseAfterMillis);
		}
		if (overallActive)
		{
			tick(now, pauseAfterMillis);
			if (overallActive)
			{
				overallAccumulatedMillis += Math.max(0, now - overallActiveSince);
				overallActive = false;
				overallPausedForLogout = true;
			}
		}
	}

	private void resumeAfterLogin(long now, long pauseAfterMillis)
	{
		for (SkillSession session : sessions.values())
		{
			session.resumeAfterLogin(now, pauseAfterMillis);
		}
		if (!overallPausedForLogout)
		{
			return;
		}

		overallPausedForLogout = false;
		if (pauseAfterMillis >= 0 && now - overallLastGainAt >= pauseAfterMillis)
		{
			return;
		}

		overallActive = true;
		overallActiveSince = now;
	}

	synchronized SessionView snapshot(TempleGameMode mode, long now, long pauseAfterMillis)
	{
		if (!initialized)
		{
			return SessionView.empty();
		}

		List<SkillView> skillViews = new ArrayList<>();
		double totalEhp = 0;
		int totalXp = 0;
		for (Skill skill : Skill.values())
		{
			SkillSession session = sessions.get(skill);
			long activeMillis = session.getActiveMillis(now, pauseAfterMillis);
			double customRate = customRateStore.getActiveRate(skill);
			double ehp = calculator.calculate(
				mode,
				skill,
				session.getStartXp(),
				session.getCurrentXp(),
				customRate);
			EhpSkillGoal goal = EhpSkillGoal.forXp(session.getCurrentXp());
			double ehpLeft = calculator.calculate(
				mode,
				skill,
				session.getCurrentXp(),
				goal.getEndXp(),
				customRate);
			int xpGained = session.getXpGained();
			totalEhp += ehp;
			totalXp += xpGained;
			skillViews.add(new SkillView(
				skill,
				session.getCurrentXp(),
				xpGained,
				ehp,
				perHour(ehp, activeMillis),
				ehpLeft,
				perHour(xpGained, activeMillis),
				activeMillis,
				session.isActive(),
				goal));
		}

		long overallMillis = overallAccumulatedMillis;
		if (overallActive)
		{
			long effectiveNow = pauseAfterMillis < 0
				? now
				: Math.min(now, overallLastGainAt + pauseAfterMillis);
			overallMillis += Math.max(0, effectiveNow - overallActiveSince);
		}
		return new SessionView(
			true,
			Collections.unmodifiableList(skillViews),
			totalEhp,
			perHour(totalEhp, overallMillis),
			totalXp,
			perHour(totalXp, overallMillis),
			overallMillis);
	}

	synchronized int getCurrentXp(Skill skill)
	{
		return initialized ? sessions.get(skill).getCurrentXp() : 0;
	}

	synchronized boolean isInitialized()
	{
		return initialized;
	}

	private static double perHour(double value, long millis)
	{
		return millis <= 0 ? 0 : value * 3_600_000D / millis;
	}

	static final class SessionView
	{
		private final boolean initialized;
		private final List<SkillView> skills;
		private final double ehpGained;
		private final double ehpPerHour;
		private final int xpGained;
		private final double xpPerHour;
		private final long activeMillis;

		private SessionView(boolean initialized, List<SkillView> skills, double ehpGained,
			double ehpPerHour, int xpGained, double xpPerHour, long activeMillis)
		{
			this.initialized = initialized;
			this.skills = skills;
			this.ehpGained = ehpGained;
			this.ehpPerHour = ehpPerHour;
			this.xpGained = xpGained;
			this.xpPerHour = xpPerHour;
			this.activeMillis = activeMillis;
		}

		static SessionView empty()
		{
			return new SessionView(false, Collections.emptyList(), 0, 0, 0, 0, 0);
		}

		boolean isInitialized()
		{
			return initialized;
		}

		List<SkillView> getSkills()
		{
			return skills;
		}

		double getEhpGained()
		{
			return ehpGained;
		}

		double getEhpPerHour()
		{
			return ehpPerHour;
		}

		int getXpGained()
		{
			return xpGained;
		}

		double getXpPerHour()
		{
			return xpPerHour;
		}

		long getActiveMillis()
		{
			return activeMillis;
		}
	}

	static final class SkillView
	{
		private final Skill skill;
		private final int currentXp;
		private final int xpGained;
		private final double ehpGained;
		private final double ehpPerHour;
		private final double ehpLeft;
		private final double xpPerHour;
		private final long activeMillis;
		private final boolean active;
		private final EhpSkillGoal goal;

		private SkillView(Skill skill, int currentXp, int xpGained, double ehpGained,
			double ehpPerHour, double ehpLeft, double xpPerHour, long activeMillis,
			boolean active, EhpSkillGoal goal)
		{
			this.skill = skill;
			this.currentXp = currentXp;
			this.xpGained = xpGained;
			this.ehpGained = ehpGained;
			this.ehpPerHour = ehpPerHour;
			this.ehpLeft = ehpLeft;
			this.xpPerHour = xpPerHour;
			this.activeMillis = activeMillis;
			this.active = active;
			this.goal = goal;
		}

		Skill getSkill()
		{
			return skill;
		}

		int getCurrentXp()
		{
			return currentXp;
		}

		int getXpGained()
		{
			return xpGained;
		}

		double getEhpGained()
		{
			return ehpGained;
		}

		double getEhpPerHour()
		{
			return ehpPerHour;
		}

		double getEhpLeft()
		{
			return ehpLeft;
		}

		double getXpPerHour()
		{
			return xpPerHour;
		}

		long getActiveMillis()
		{
			return activeMillis;
		}

		boolean isActive()
		{
			return active;
		}

		EhpSkillGoal getGoal()
		{
			return goal;
		}
	}
}

package io.github.veganismftw.templeehptracker;

import net.runelite.client.events.ConfigChanged;

final class CanvasOverlaySettings
{
	private volatile CanvasMetric primary = CanvasMetric.EHP_GAINED;
	private volatile CanvasSecondaryMetric secondary = CanvasSecondaryMetric.EHP_PER_HOUR;
	private volatile boolean showIcon = true;
	private volatile boolean showProgress = true;
	private volatile boolean showActiveTime = true;

	void load(TempleEhpConfig config)
	{
		primary = config.canvasPrimaryMetric();
		secondary = config.canvasSecondaryMeasurement();
		showIcon = config.showCanvasSkillIcon();
		showProgress = config.showCanvasProgressBar();
		showActiveTime = config.showCanvasActiveTime();
	}

	boolean apply(ConfigChanged event)
	{
		String value = event.getNewValue();
		try
		{
			switch (event.getKey())
			{
				case TempleEhpConfig.CANVAS_PRIMARY_KEY:
					primary = value == null ? CanvasMetric.EHP_GAINED : CanvasMetric.valueOf(value);
					return true;
				case TempleEhpConfig.CANVAS_SECONDARY_KEY:
					secondary = value == null
						? CanvasSecondaryMetric.EHP_PER_HOUR
						: CanvasSecondaryMetric.valueOf(value);
					return true;
				case TempleEhpConfig.CANVAS_ICON_KEY:
					showIcon = value == null || Boolean.parseBoolean(value);
					return true;
				case TempleEhpConfig.CANVAS_PROGRESS_KEY:
					showProgress = value == null || Boolean.parseBoolean(value);
					return true;
				case TempleEhpConfig.CANVAS_ACTIVE_TIME_KEY:
					showActiveTime = value == null || Boolean.parseBoolean(value);
					return true;
				default:
					return false;
			}
		}
		catch (IllegalArgumentException ignored)
		{
			return false;
		}
	}

	CanvasMetric getPrimary()
	{
		return primary;
	}

	CanvasSecondaryMetric getSecondary()
	{
		return secondary;
	}

	boolean isShowIcon()
	{
		return showIcon;
	}

	boolean isShowProgress()
	{
		return showProgress;
	}

	boolean isShowActiveTime()
	{
		return showActiveTime;
	}
}

package io.github.veganismftw.templeehptracker;

import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

@Singleton
final class CustomRateStore
{
	private static final String ENABLED_PREFIX = "customEnabled.";
	private static final String RATE_PREFIX = "customRate.";
	private final ConfigManager configManager;

	@Inject
	CustomRateStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	boolean isEnabled(Skill skill)
	{
		return Boolean.parseBoolean(configManager.getConfiguration(
			TempleEhpConfig.GROUP, ENABLED_PREFIX + key(skill)));
	}

	double getRate(Skill skill)
	{
		String value = configManager.getConfiguration(TempleEhpConfig.GROUP, RATE_PREFIX + key(skill));
		if (value == null)
		{
			return 0;
		}
		try
		{
			double rate = Double.parseDouble(value);
			return rate > 0 ? rate : 0;
		}
		catch (NumberFormatException ignored)
		{
			return 0;
		}
	}

	double getActiveRate(Skill skill)
	{
		return isEnabled(skill) ? getRate(skill) : 0;
	}

	void setEnabled(Skill skill, boolean enabled)
	{
		configManager.setConfiguration(TempleEhpConfig.GROUP, ENABLED_PREFIX + key(skill), enabled);
	}

	void setRate(Skill skill, double rate)
	{
		if (rate > 0)
		{
			configManager.setConfiguration(TempleEhpConfig.GROUP, RATE_PREFIX + key(skill), rate);
		}
	}

	void reset(Skill skill)
	{
		configManager.unsetConfiguration(TempleEhpConfig.GROUP, ENABLED_PREFIX + key(skill));
		configManager.unsetConfiguration(TempleEhpConfig.GROUP, RATE_PREFIX + key(skill));
	}

	private static String key(Skill skill)
	{
		return skill.name().toLowerCase(Locale.ENGLISH);
	}
}

package io.github.veganismftw.templeehptracker;

final class SkillSession
{
	private int startXp;
	private int currentXp;
	private long accumulatedMillis;
	private long activeSince;
	private long lastGainAt;
	private boolean active;
	private boolean pausedForLogout;

	void initialize(int xp)
	{
		startXp = xp;
		currentXp = xp;
		accumulatedMillis = 0;
		activeSince = 0;
		lastGainAt = 0;
		active = false;
		pausedForLogout = false;
	}

	boolean update(int xp, long now)
	{
		if (xp < currentXp)
		{
			initialize(xp);
			return false;
		}
		if (xp == currentXp)
		{
			return false;
		}

		if (!active)
		{
			active = true;
			activeSince = now;
		}
		lastGainAt = now;
		currentXp = xp;
		return true;
	}

	void reconcile(int xp)
	{
		if (xp < currentXp)
		{
			initialize(xp);
			return;
		}
		int offlineGain = xp - currentXp;
		startXp += offlineGain;
		currentXp = xp;
	}

	void applyIdlePause(long now, long pauseAfterMillis)
	{
		if (pauseAfterMillis < 0 || !active || now - lastGainAt < pauseAfterMillis)
		{
			return;
		}
		long pauseAt = lastGainAt + pauseAfterMillis;
		accumulatedMillis += Math.max(0, pauseAt - activeSince);
		active = false;
	}

	void pauseForLogout(long now, long pauseAfterMillis)
	{
		applyIdlePause(now, pauseAfterMillis);
		if (active)
		{
			accumulatedMillis += Math.max(0, now - activeSince);
			active = false;
			pausedForLogout = true;
		}
	}

	void resumeAfterLogin(long now, long pauseAfterMillis)
	{
		if (!pausedForLogout)
		{
			return;
		}

		pausedForLogout = false;
		if (pauseAfterMillis >= 0 && now - lastGainAt >= pauseAfterMillis)
		{
			return;
		}

		active = true;
		activeSince = now;
	}

	long getActiveMillis(long now, long pauseAfterMillis)
	{
		if (!active)
		{
			return accumulatedMillis;
		}
		long effectiveNow = pauseAfterMillis < 0
			? now
			: Math.min(now, lastGainAt + pauseAfterMillis);
		return accumulatedMillis + Math.max(0, effectiveNow - activeSince);
	}

	int getStartXp()
	{
		return startXp;
	}

	int getCurrentXp()
	{
		return currentXp;
	}

	int getXpGained()
	{
		return Math.max(0, currentXp - startXp);
	}

	boolean isActive()
	{
		return active;
	}
}

package io.github.veganismftw.templeehptracker;

import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/**
 * Produces an offline lifetime estimate from the bundled rate snapshot.
 *
 * <p>This deliberately ignores custom rates. Until the bundled model includes
 * every TempleOSRS BXP and special-function rule, callers must label the result
 * as an estimate rather than canonical Temple EHP.</p>
 */
@Singleton
final class LifetimeEhpCalculator
{
	private final EhpCalculator calculator;

	@Inject
	LifetimeEhpCalculator(EhpCalculator calculator)
	{
		this.calculator = calculator;
	}

	LifetimeView calculate(TempleGameMode mode, Map<Skill, Integer> currentXp,
		int playtimeMinutes, boolean playtimeAvailable)
	{
		double estimatedEhp = 0;
		for (Map.Entry<Skill, Integer> entry : currentXp.entrySet())
		{
			estimatedEhp += calculator.calculate(
				mode,
				entry.getKey(),
				0,
				Math.max(0, entry.getValue()),
				0);
		}

		boolean hasPlaytime = playtimeAvailable && playtimeMinutes > 0;
		double efficiency = hasPlaytime
			? efficiencyPercent(estimatedEhp, playtimeMinutes)
			: 0;
		return new LifetimeView(estimatedEhp, playtimeMinutes, hasPlaytime, efficiency);
	}

	static double efficiencyPercent(double totalEhp, int playtimeMinutes)
	{
		if (totalEhp < 0 || playtimeMinutes <= 0)
		{
			return 0;
		}
		return totalEhp * 60D * 100D / playtimeMinutes;
	}

	static final class LifetimeView
	{
		private final double estimatedEhp;
		private final int playtimeMinutes;
		private final boolean playtimeAvailable;
		private final double efficiencyPercent;

		private LifetimeView(double estimatedEhp, int playtimeMinutes,
			boolean playtimeAvailable, double efficiencyPercent)
		{
			this.estimatedEhp = estimatedEhp;
			this.playtimeMinutes = playtimeMinutes;
			this.playtimeAvailable = playtimeAvailable;
			this.efficiencyPercent = efficiencyPercent;
		}

		double getEstimatedEhp()
		{
			return estimatedEhp;
		}

		int getPlaytimeMinutes()
		{
			return playtimeMinutes;
		}

		boolean isPlaytimeAvailable()
		{
			return playtimeAvailable;
		}

		double getEfficiencyPercent()
		{
			return efficiencyPercent;
		}
	}
}

package io.github.veganismftw.templeehptracker;

final class AccountModeResolver
{
	// Values published for Varbits.ACCOUNT_TYPE by RuneLite's API.
	private static final int NORMAL = 0;
	private static final int IRONMAN = 1;
	private static final int ULTIMATE_IRONMAN = 2;
	private static final int HARDCORE_IRONMAN = 3;
	private static final int GROUP_IRONMAN = 4;
	private static final int HARDCORE_GROUP_IRONMAN = 5;
	private static final int UNRANKED_GROUP_IRONMAN = 6;

	private AccountModeResolver()
	{
	}

	static TempleGameMode resolve(GameModeSetting setting, int accountType, int combatLevel)
	{
		if (setting != GameModeSetting.AUTO)
		{
			return setting.asTempleMode();
		}

		switch (accountType)
		{
			case ULTIMATE_IRONMAN:
				return TempleGameMode.ULTIMATE_IRON;
			case IRONMAN:
			case HARDCORE_IRONMAN:
			case GROUP_IRONMAN:
			case HARDCORE_GROUP_IRONMAN:
			case UNRANKED_GROUP_IRONMAN:
				return TempleGameMode.IRON;
			case NORMAL:
			default:
				return combatLevel == 3 ? TempleGameMode.LEVEL_3 : TempleGameMode.MAIN;
		}
	}
}

