	void update(EhpSession.SessionView view, String modeLabel,
		LifetimeEhpCalculator.LifetimeView lifetimeView)
	{
		status.setText(view.isInitialized() ? modeLabel : "Log in to begin");
		ehpGained.setText(htmlLabel("EHP gained", UiFormat.ehp(view.getEhpGained())));
		ehpPerHour.setText(htmlLabel("EHP/h", UiFormat.ehpRate(view.getEhpPerHour())));
		xpGained.setText(htmlLabel("XP gained", UiFormat.integer(view.getXpGained())));
		xpPerHour.setText(htmlLabel("XP/h", UiFormat.integer(view.getXpPerHour())));
		activeTime.setText(htmlLabel("Active time", UiFormat.duration(view.getActiveMillis())));
		overallXpRows.setVisible(config.displayMode() == DisplayMode.XP_AND_EHP);
		lifetimeSummary.setVisible(config.showLifetimeSummary() && view.isInitialized());
		if (lifetimeView != null)
		{
			estimatedTotalEhp.setText(htmlLabel("Est. total EHP", UiFormat.ehp(lifetimeView.getEstimatedEhp())));
			if (lifetimeView.isPlaytimeAvailable())
			{
				playedTime.setText(htmlLabel("Time played", UiFormat.playedTime(lifetimeView.getPlaytimeMinutes())));
				playedTime.setToolTipText(null);
				lifetimeEfficiency.setText(htmlLabel(
					"Est. efficiency", UiFormat.percent(lifetimeView.getEfficiencyPercent())));
			}
			else
			{
				playedTime.setText(htmlLabel("Time played", "Unavailable"));
				playedTime.setToolTipText("Open Account Summary and reveal Time played to load this value.");
				lifetimeEfficiency.setText(htmlLabel("Est. efficiency", "Unavailable"));
			}
		}

		skillList.removeAll();
		for (EhpSession.SkillView skillView : view.getSkills())
		{
			if (!config.showInactiveSkills() && skillView.getXpGained() == 0)
			{
				continue;
			}
			SkillTrackerCard card = cards.get(skillView.getSkill());
			card.update(skillView, config.displayMode(), config.showSidebarActiveTime());
			card.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
			skillList.add(card);
		}
		skillList.revalidate();
		skillList.repaint();
	}

	private static void setSmallFont(JLabel label)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	private static String htmlLabel(String key, String value)
	{
		return String.format(HTML_LABEL, ColorUtil.toHexColor(ColorScheme.LIGHT_GRAY_COLOR), key, value);
	}

	private static void installPopupMenu(Component component, JPopupMenu popupMenu)
	{
		if (component instanceof JComponent)
		{
			((JComponent) component).setComponentPopupMenu(popupMenu);
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				installPopupMenu(child, popupMenu);
			}
		}
	}
}

package io.github.veganismftw.templeehptracker;

import net.runelite.api.Skill;

final class OverallCanvasProgress
{
	private final int totalLevel;
	private final int maximumTotalLevel;
	private final double progress;

	private OverallCanvasProgress(int totalLevel, int maximumTotalLevel, double progress)
	{
		this.totalLevel = totalLevel;
		this.maximumTotalLevel = maximumTotalLevel;
		this.progress = progress;
	}

	static OverallCanvasProgress from(EhpSession.SessionView view)
	{
		int totalLevel = 0;
		int skillCount = 0;
		double fractionalLevels = 0;
		for (EhpSession.SkillView skillView : view.getSkills())
		{
			if (skillView.getSkill() == Skill.OVERALL)
			{
				continue;
			}
			int level = Math.min(99, skillView.getGoal().getStartLevel());
			totalLevel += level;
			skillCount++;
			fractionalLevels += level;
			if (level < 99)
			{
				fractionalLevels += skillView.getGoal().getProgress() / 100D;
			}
		}

		int maximumTotalLevel = skillCount * 99;
		double progress = maximumTotalLevel <= 0
			? 0 : fractionalLevels * 100D / maximumTotalLevel;
		return new OverallCanvasProgress(totalLevel, maximumTotalLevel,
			Math.max(0, Math.min(100, progress)));
	}

	int getTotalLevel()
	{
		return totalLevel;
	}

	int getMaximumTotalLevel()
	{
		return maximumTotalLevel;
	}

	double getProgress()
	{
		return progress;
	}
}

package io.github.veganismftw.templeehptracker;

import java.util.List;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
final class EhpCalculator
{
	private static final double EPSILON = 1e-9;
	private final TempleRateRepository repository;

	@Inject
	EhpCalculator(TempleRateRepository repository)
	{
		this.repository = repository;
	}

	double calculate(TempleGameMode mode, Skill skill, int startXp, int endXp, double customRate)
	{
		if (endXp <= startXp)
		{
			return 0;
		}
		if (customRate > 0)
		{
			return (endXp - startXp) / customRate;
		}

		Optional<TempleRateSnapshot.SkillRates> optionalRates = repository.getRates(mode, skill);
		if (!optionalRates.isPresent())
		{
			return 0;
		}

		TempleRateSnapshot.SkillRates rates = optionalRates.get();
		List<TempleRateSnapshot.RateRow> rows = rates.getRows();
		double ehp = 0;
		double cursor = startXp;
		while (cursor < endXp)
		{
			int rowIndex = rowIndexAt(rows, cursor);
			if (rowIndex < 0)
			{
				break;
			}

			TempleRateSnapshot.RateRow row = rows.get(rowIndex);
			double segmentEnd = rowIndex + 1 < rows.size()
				? Math.min(endXp, rows.get(rowIndex + 1).getXp())
				: endXp;
			if (segmentEnd <= cursor)
			{
				break;
			}

			if (row.isDirect() && row.getRate() > 0)
			{
				if (rates.isInterpolate() && rowIndex + 1 < rows.size())
				{
					TempleRateSnapshot.RateRow next = rows.get(rowIndex + 1);
					if (next.isDirect() && next.getRate() > 0)
					{
						ehp += integrateLinearRate(row, next, cursor, segmentEnd);
					}
					else
					{
						ehp += (segmentEnd - cursor) / row.getRate();
					}
				}
				else
				{
					ehp += (segmentEnd - cursor) / row.getRate();
				}
			}
			cursor = segmentEnd;
		}
		return ehp;
	}

	RateView getRateAt(TempleGameMode mode, Skill skill, int xp, double customRate)
	{
		if (customRate > 0)
		{
			return new RateView(customRate, "Custom constant rate", true, true);
		}

		Optional<TempleRateSnapshot.SkillRates> optionalRates = repository.getRates(mode, skill);
		if (!optionalRates.isPresent())
		{
			return RateView.unavailable();
		}
		TempleRateSnapshot.SkillRates rates = optionalRates.get();
		List<TempleRateSnapshot.RateRow> rows = rates.getRows();
		int index = rowIndexAt(rows, xp);
		if (index < 0)
		{
			return RateView.unavailable();
		}
		TempleRateSnapshot.RateRow row = rows.get(index);
		double effectiveRate = row.getRate();
		if (rates.isInterpolate() && row.isDirect() && index + 1 < rows.size())
		{
			TempleRateSnapshot.RateRow next = rows.get(index + 1);
			if (next.isDirect() && next.getRate() > 0)
			{
				effectiveRate = interpolate(row, next, xp);
			}
		}
		return new RateView(effectiveRate, row.getMethod(), row.isDirect(), false);
	}

	private static int rowIndexAt(List<TempleRateSnapshot.RateRow> rows, double xp)
	{
		int result = -1;
		for (int i = 0; i < rows.size(); i++)
		{
			if (rows.get(i).getXp() > xp)
			{
				break;
			}
			result = i;
		}
		return result;
	}

	private static double interpolate(TempleRateSnapshot.RateRow first, TempleRateSnapshot.RateRow second, double xp)
	{
		double width = second.getXp() - first.getXp();
		if (width <= 0)
		{
			return first.getRate();
		}
		double fraction = (xp - first.getXp()) / width;
		return first.getRate() + fraction * (second.getRate() - first.getRate());
	}

	private static double integrateLinearRate(
		TempleRateSnapshot.RateRow first,
		TempleRateSnapshot.RateRow second,
		double start,
		double end)
	{
		double slope = (second.getRate() - first.getRate()) / (second.getXp() - first.getXp());
		if (Math.abs(slope) < EPSILON)
		{
			return (end - start) / first.getRate();
		}
		double startRate = interpolate(first, second, start);
		double endRate = interpolate(first, second, end);
		return Math.log(endRate / startRate) / slope;
	}

	static final class RateView
	{
		private final double rate;
		private final String method;
		private final boolean direct;
		private final boolean custom;

		private RateView(double rate, String method, boolean direct, boolean custom)
		{
			this.rate = rate;
			this.method = method;
			this.direct = direct;
			this.custom = custom;
		}

		static RateView unavailable()
		{
			return new RateView(0, "No direct EHP rate published", false, false);
		}

		double getRate()
		{
			return rate;
		}

		String getMethod()
		{
			return method;
		}

		boolean isDirect()
		{
			return direct;
		}

		boolean isCustom()
		{
			return custom;
		}
	}
}

