package io.github.veganismftw.templeehptracker;

import net.runelite.api.Skill;

public enum CanvasMetric
{
	EHP_GAINED("EHP gained")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.ehp(view.getEhpGained());
		}
	},
	EHP_PER_HOUR("EHP/h")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.ehp(view.getEhpPerHour());
		}
	},
	EHP_LEFT("EHP left")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.ehp(view.getEhpLeft());
		}
	},
	XP_GAINED("XP gained")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.integer(view.getXpGained());
		}
	},
	XP_PER_HOUR("XP/h")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.integer(view.getXpPerHour());
		}
	},
	XP_LEFT("XP left")
	{
		@Override
		String format(EhpSession.SkillView view)
		{
			return UiFormat.integer(Math.max(0, view.getGoal().getEndXp() - view.getCurrentXp()));
		}
	};

	private final String label;

	CanvasMetric(String label)
	{
		this.label = label;
	}

	String getLabel()
	{
		return label;
	}

	abstract String format(EhpSession.SkillView view);

	String format(EhpSession.SessionView view)
	{
		switch (this)
		{
			case EHP_GAINED:
				return UiFormat.ehp(view.getEhpGained());
			case EHP_PER_HOUR:
				return UiFormat.ehpRate(view.getEhpPerHour());
			case EHP_LEFT:
				double ehpLeft = 0;
				for (EhpSession.SkillView skillView : view.getSkills())
				{
					if (skillView.getSkill() != Skill.OVERALL)
					{
						ehpLeft += skillView.getEhpLeft();
					}
				}
				return UiFormat.ehp(ehpLeft);
			case XP_GAINED:
				return UiFormat.integer(view.getXpGained());
			case XP_PER_HOUR:
				return UiFormat.integer(view.getXpPerHour());
			case XP_LEFT:
				long xpLeft = 0;
				for (EhpSession.SkillView skillView : view.getSkills())
				{
					if (skillView.getSkill() != Skill.OVERALL)
					{
						xpLeft += Math.max(0,
							skillView.getGoal().getEndXp() - skillView.getCurrentXp());
					}
				}
				return UiFormat.integer(xpLeft);
			default:
				throw new IllegalStateException("Unhandled canvas metric " + this);
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package io.github.veganismftw.templeehptracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

final class EhpOverallOverlay extends OverlayPanel
{
	private static final int BORDER_SIZE = 2;
	private static final Rectangle HEADER_BORDER = new Rectangle(2, 1, 4, 0);
	private static final Color OVERALL_PROGRESS_COLOR = new Color(117, 142, 72);
	private final TempleEhpPlugin plugin;
	private final CanvasOverlaySettings settings;
	private final BufferedImage icon;
	private final PanelComponent header = new PanelComponent();
	private final PanelComponent stats = new PanelComponent();
	private int previousLayoutWidth = -1;

	EhpOverallOverlay(TempleEhpPlugin plugin, CanvasOverlaySettings settings, BufferedImage icon)
	{
		super(plugin);
		this.plugin = plugin;
		this.settings = settings;
		this.icon = icon;

		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, 2));
		header.setBorder(HEADER_BORDER);
		header.setBackgroundColor(null);
		stats.setBorder(new Rectangle());
		stats.setGap(new Point(0, 0));
		stats.setOrientation(ComponentOrientation.VERTICAL);
		stats.setBackgroundColor(null);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "EHP Tracker total overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		EhpSession.SessionView view = plugin.getSessionView();
		if (view == null || !view.isInitialized())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		header.getChildren().clear();
		stats.getChildren().clear();
		CanvasMetric primary = settings.getPrimary();
		CanvasSecondaryMetric secondarySetting = settings.getSecondary();
		CanvasMetric secondary = secondarySetting == null ? null : secondarySetting.getMetric();
		String primaryValue = primary.format(view);
		String secondaryValue = secondary == null ? null : secondary.format(view);
		String activeTime = UiFormat.duration(view.getActiveMillis());
		stats.getChildren().add(line(primary.getLabel(), primaryValue));
		if (secondary != null)
		{
			stats.getChildren().add(line(secondary.getLabel(), secondaryValue));
		}
		boolean showIcon = settings.isShowIcon();
		int preferredWidth = CanvasOverlayLayout.preferredWidth(
			graphics,
			showIcon ? icon.getWidth() : 0,
			settings.isShowProgress() ? CanvasOverlayLayout.PROGRESS_BAR_MINIMUM_WIDTH : 0,
			primary.getLabel(), primaryValue,
			secondary == null ? null : secondary.getLabel(), secondaryValue,
			settings.isShowActiveTime() ? "Active time" : null,
			settings.isShowActiveTime() ? activeTime : null);
		updatePreferredWidth(preferredWidth);

		if (showIcon)
		{
			header.getChildren().add(SplitComponent.builder()
				.first(new ImageComponent(icon))
				.second(stats)
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(new Point(4, 0))
				.build());
		}
		else
		{
			header.getChildren().add(stats);
		}
		panelComponent.getChildren().add(header);
		if (settings.isShowProgress())
		{
			OverallCanvasProgress overallProgress = OverallCanvasProgress.from(view);
			ProgressBarComponent progress = new ProgressBarComponent();
			progress.setMinimum(0);
			progress.setMaximum(100);
			progress.setValue(overallProgress.getProgress());
			progress.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
			progress.setBackgroundColor(new Color(61, 56, 49));
			progress.setForegroundColor(OVERALL_PROGRESS_COLOR);
			progress.setLeftLabel(String.valueOf(overallProgress.getTotalLevel()));
			progress.setCenterLabel(UiFormat.percent(overallProgress.getProgress()));
			progress.setRightLabel(String.valueOf(overallProgress.getMaximumTotalLevel()));
			panelComponent.getChildren().add(progress);
		}
		if (settings.isShowActiveTime())
		{
			panelComponent.getChildren().add(line("Active time", activeTime));
		}
		return super.render(graphics);
	}

	@Override
	public String getName()
	{
		return super.getName() + " Total";
	}

	private static LineComponent line(String label, String value)
	{
		return LineComponent.builder()
			.left(label + ":")
			.right(value)
			.build();
	}

	private void updatePreferredWidth(int width)
	{
		if (previousLayoutWidth >= 0 && previousLayoutWidth != width)
		{
			Dimension resized = CanvasOverlayLayout.resizeUserWidth(
				getPreferredSize(), previousLayoutWidth, width);
			if (resized != null)
			{
				setPreferredSize(resized);
			}
		}
		previousLayoutWidth = width;
		panelComponent.setPreferredSize(new Dimension(width, 0));
	}
}

package io.github.veganismftw.templeehptracker;

import com.google.inject.Provides;
import java.awt.Rectangle;
