@PluginDescriptor(
	name = "EHP Tracker",
	description = "Tracks session EHP using TempleOSRS skilling rates",
	tags = {"ehp", "experience", "skilling", "temple", "templeosrs", "tracker"}
)
@Slf4j
public class TempleEhpPlugin extends Plugin
{
	private static final String ADD_TO_CANVAS = "Add EHP to canvas";
	private static final String REMOVE_FROM_CANVAS = "Remove EHP from canvas";
	private static final int[] TOTAL_LEVEL_WIDGETS =
	{
		InterfaceID.Stats.TOTAL,
		InterfaceID.Stats.TOTAL_GRAPHIC0,
		InterfaceID.Stats.TOTAL_GRAPHIC1,
		InterfaceID.Stats.TOTAL_GRAPHIC2,
		InterfaceID.Stats.TOTAL_GRAPHIC3,
		InterfaceID.Stats.TOTAL_GRAPHIC4,
		InterfaceID.Stats.TOTAL_GRAPHIC5,
		InterfaceID.Stats.TOTAL_TEXT6
	};
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private TempleEhpConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private TempleRateRepository repository;

	@Inject
	private EhpCalculator calculator;

	@Inject
	private LifetimeEhpCalculator lifetimeCalculator;

	@Inject
	private CustomRateStore customRateStore;

	@Inject
	private EhpSession session;

	@Inject
	private OverlayManager overlayManager;

	private NavigationButton navigationButton;
	private BufferedImage pluginIcon;
	private TempleEhpPanel panel;
	private TempleGameMode effectiveMode = TempleGameMode.MAIN;
	private long lastAccount = -1;
	private int initializeTicks;
	private boolean resetAfterLogin;
	private volatile Map<Skill, EhpSession.SkillView> latestSkillViews = Collections.emptyMap();
	private volatile EhpSession.SessionView latestSessionView = EhpSession.SessionView.empty();
	private volatile int playtimeMinutes;
	private volatile boolean playtimeAvailable;
	private final CanvasOverlaySettings canvasOverlaySettings = new CanvasOverlaySettings();

	@Provides
	TempleEhpConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TempleEhpConfig.class);
	}

	@Override
	protected void startUp()
	{
		canvasOverlaySettings.load(config);
		panel = new TempleEhpPanel(this, config, repository, session, calculator,
			customRateStore, skillIconManager);
		pluginIcon = ImageUtil.loadImageResource(getClass(), "/temple-ehp-icon.png");
		navigationButton = NavigationButton.builder()
			.tooltip("EHP Tracker")
			.icon(pluginIcon)
			.priority(3)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);

		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				lastAccount = client.getAccountHash();
				initializeTicks = 2;
				resetAfterLogin = !session.isInitialized();
			}
			updateEffectiveMode();
		});
		log.debug("EHP Tracker started with rate snapshot {}", repository.getGeneratedDate());
	}

	@Override
	protected void shutDown()
	{
		removeAllOverlays();
		latestSkillViews = Collections.emptyMap();
		latestSessionView = EhpSession.SessionView.empty();
		playtimeMinutes = 0;
		playtimeAvailable = false;
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		panel = null;
		pluginIcon = null;
		log.debug("EHP Tracker stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING)
		{
			initializeTicks = 2;
			// A world hop is part of the live session. Keep active timers running so
			// EHP/h measures real elapsed time rather than logged-in-only time.
		}
		else if (state == GameState.LOGGED_IN)
		{
			long account = client.getAccountHash();
			if (account != lastAccount)
			{
				removeAllOverlays();
				lastAccount = account;
				initializeTicks = 2;
				resetAfterLogin = true;
			}
			updateEffectiveMode();
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR)
		{
			playtimeMinutes = 0;
			playtimeAvailable = false;
		}
	}

	static boolean isLoggedInForTracking(GameState state)
	{
		return state.getState() >= GameState.LOADING.getState();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		updateEffectiveMode();
		updatePlaytimeState();
		if (initializeTicks > 0 && --initializeTicks == 0)
		{
			Map<Skill, Integer> currentXp = readCurrentXp();
			if (resetAfterLogin || !session.isInitialized())
			{
				session.initialize(currentXp);
			}
			else
			{
				// Preserve the session across hops and omit XP gained while logged out.
				session.reconcile(currentXp);
			}
			resetAfterLogin = false;
			refreshPanel();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (initializeTicks > 0)
		{
			// RuneLite emits an XP synchronization burst during login.
			return;
		}
		session.update(event.getSkill(), event.getXp(), System.currentTimeMillis());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (TempleEhpConfig.GROUP.equals(event.getGroup()))
		{
			canvasOverlaySettings.apply(event);
			settingsChanged();
		}
	}

	@Subscribe
	@SuppressWarnings("deprecation")
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		int widgetId = event.getActionParam1();
		if (!config.skillTabCanvasMenu()
			|| WidgetUtil.componentToInterface(widgetId) != InterfaceID.STATS)
		{
			return;
		}
		if (isStatsTotalWidget(widgetId))
		{
			return;
		}
		if (!event.getOption().startsWith("View"))
		{
			return;
		}

		String[] optionParts = event.getOption().split(" ");
		if (optionParts.length < 2)
		{
			return;
		}
		String skillText = optionParts[1];
		Skill skill;
		try
		{
			skill = Skill.valueOf(Text.removeTags(skillText).toUpperCase(Locale.ENGLISH));
		}
		catch (IllegalArgumentException ignored)
		{
			return;
		}

		client.createMenuEntry(-1)
			.setTarget(skillText)
			.setOption(hasOverlay(skill) ? REMOVE_FROM_CANVAS : ADD_TO_CANVAS)
			.setType(MenuAction.RUNELITE)
			.onClick(click ->
			{
				if (hasOverlay(skill))
				{
					removeOverlay(skill);
				}
				else
				{
					addOverlay(skill);
				}
			});
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.skillTabCanvasMenu() || !isMouseOverTotalLevel())
		{
			return;
		}

		client.createMenuEntry(-1)
			.setTarget("Total level")
			.setOption(hasOverallOverlay() ? REMOVE_FROM_CANVAS : ADD_TO_CANVAS)
			.setType(MenuAction.RUNELITE)
			.onClick(click ->
			{
				if (hasOverallOverlay())
				{
					removeOverallOverlay();
				}
				else
				{
					addOverallOverlay();
				}
			});
	}

	@Schedule(period = 1, unit = ChronoUnit.SECONDS)
	public void onSecond()
	{
		long now = System.currentTimeMillis();
		long pauseAfterMillis = pauseAfterMillis();
		session.tickLogout(
			config.pauseOnLogout(),
			isLoggedInForTracking(client.getGameState()),
			now,
			pauseAfterMillis);
		session.tick(now, pauseAfterMillis);
		refreshPanel();
	}

	void resetSession()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				session.reset(readCurrentXp());
				removeAllOverlays();
				refreshPanel();
			}
		});
	}

	void settingsChanged()
	{
		clientThread.invokeLater(() ->
		{
			updateEffectiveMode();
			updatePlaytimeState();
			TempleEhpPanel currentPanel = panel;
			if (currentPanel != null)
			{
				SwingUtilities.invokeLater(currentPanel::invalidateRates);
			}
			refreshPanel();
		});
	}

	void setGameMode(GameModeSetting setting)
	{
		if (setting != null)
		{
			configManager.setConfiguration(TempleEhpConfig.GROUP, TempleEhpConfig.GAME_MODE_KEY, setting);
		}
	}

	void addOverlay(Skill skill)
	{
		removeOverlay(skill);
		overlayManager.add(new EhpInfoBoxOverlay(
			this, canvasOverlaySettings, skill, skillIconManager.getSkillImage(skill)));
	}

	void addOverallOverlay()
	{
		removeOverallOverlay();
		BufferedImage overallSkillIcon = spriteManager.getSprite(overallSpriteId(), 0);
		if (overallSkillIcon != null)
		{
			overlayManager.add(new EhpOverallOverlay(this, canvasOverlaySettings, overallSkillIcon));
		}
	}

	static int overallSpriteId()
	{
		return SpriteID.SideIcons.STATS;
	}

	void removeOverallOverlay()
	{
		overlayManager.removeIf(overlay -> overlay instanceof EhpOverallOverlay);
	}

	boolean hasOverallOverlay()
	{
		return overlayManager.anyMatch(overlay -> overlay instanceof EhpOverallOverlay);
	}

	void removeOverlay(Skill skill)
	{
		overlayManager.removeIf(overlay -> overlay instanceof EhpInfoBoxOverlay
			&& ((EhpInfoBoxOverlay) overlay).getSkill() == skill);
	}

	boolean hasOverlay(Skill skill)
	{
		return overlayManager.anyMatch(overlay -> overlay instanceof EhpInfoBoxOverlay
			&& ((EhpInfoBoxOverlay) overlay).getSkill() == skill);
	}

	EhpSession.SkillView getSkillView(Skill skill)
	{
		return latestSkillViews.get(skill);
	}

	EhpSession.SessionView getSessionView()
	{
		return latestSessionView;
	}

	static boolean containsPoint(Rectangle bounds, net.runelite.api.Point point)
	{
		return bounds != null && point != null && bounds.contains(point.getX(), point.getY());
	}

	private static boolean isStatsTotalWidget(int widgetId)
	{
		for (int totalWidgetId : TOTAL_LEVEL_WIDGETS)
		{
			if (widgetId == totalWidgetId)
			{
				return true;
			}
		}
		return false;
	}

	private void updateEffectiveMode()
	{
		int accountType = getNativeAccountType();
		Player localPlayer = client.getLocalPlayer();
		int combatLevel = localPlayer == null ? 0 : localPlayer.getCombatLevel();
		effectiveMode = AccountModeResolver.resolve(config.gameMode(), accountType, combatLevel);
	}

	@SuppressWarnings("deprecation")
	private int getNativeAccountType()
	{
		// ACCOUNT_TYPE has no gameval replacement; this is the server-backed native value.
		return client.getGameState() == GameState.LOGGED_IN
			? client.getVarbitValue(Varbits.ACCOUNT_TYPE) : 0;
	}

	private Map<Skill, Integer> readCurrentXp()
	{
		Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			currentXp.put(skill, Math.max(0, client.getSkillExperience(skill)));
		}
		return currentXp;
	}

	private void refreshPanel()
	{
		TempleEhpPanel currentPanel = panel;
		if (currentPanel == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		TempleGameMode mode = effectiveMode;
		EhpSession.SessionView view = session.snapshot(mode, now, pauseAfterMillis());
		Map<Skill, EhpSession.SkillView> skillViews = new EnumMap<>(Skill.class);
		for (EhpSession.SkillView skillView : view.getSkills())
		{
			skillViews.put(skillView.getSkill(), skillView);
		}
		latestSkillViews = Collections.unmodifiableMap(skillViews);
		latestSessionView = view;
		Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
		for (EhpSession.SkillView skillView : view.getSkills())
		{
			currentXp.put(skillView.getSkill(), skillView.getCurrentXp());
		}
		LifetimeEhpCalculator.LifetimeView lifetimeView = config.showLifetimeSummary()
			? lifetimeCalculator.calculate(mode, currentXp, playtimeMinutes, playtimeAvailable)
			: null;
		String modeLabel = config.gameMode() == GameModeSetting.AUTO
			? "Auto: " + mode : mode.toString();
		SwingUtilities.invokeLater(() -> currentPanel.refresh(view, mode, modeLabel, lifetimeView));
	}

	private void updatePlaytimeState()
	{
		if (!config.showLifetimeSummary() || client.getGameState() != GameState.LOGGED_IN)
		{
			playtimeMinutes = 0;
			playtimeAvailable = false;
			return;
		}

		boolean displayEnabled = client.getVarbitValue(VarbitID.ACCOUNT_SUMMARY_DISPLAY_PLAYTIME) != 0;
		int minutes = Math.max(0, client.getVarcIntValue(VarClientID.ACCOUNT_SUMMARY_PLAYTIME));
		playtimeMinutes = minutes;
		playtimeAvailable = displayEnabled && minutes > 0;
	}

	private long pauseAfterMillis()
	{
		int minutes = config.pauseAfterMinutes();
		return minutes == 0 ? -1 : minutes * 60_000L;
	}

	private void removeAllOverlays()
	{
		overlayManager.removeIf(overlay -> overlay instanceof EhpInfoBoxOverlay
			|| overlay instanceof EhpOverallOverlay);
	}

	private boolean isMouseOverTotalLevel()
	{
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		for (int widgetId : TOTAL_LEVEL_WIDGETS)
		{
			Widget widget = client.getWidget(widgetId);
			if (widget != null && !widget.isHidden() && containsPoint(widget.getBounds(), mouse))
			{
				return true;
			}
		}
		return false;
	}
}

package io.github.veganismftw.templeehptracker;

import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.time.Duration;

final class UiFormat
{
	private static final DecimalFormat INTEGER = new DecimalFormat("#,##0");
	private static final DecimalFormat EHP = new DecimalFormat("0.00");
	private static final DecimalFormat PERCENT = new DecimalFormat("0.00");

	static
	{
		PERCENT.setRoundingMode(RoundingMode.DOWN);
	}

	private UiFormat()
	{
	}

	static synchronized String integer(double value)
	{
		return INTEGER.format(value);
	}

	static synchronized String ehp(double value)
	{
		return EHP.format(value);
	}

	static synchronized String ehpRate(double value)
	{
		return EHP.format(value);
	}

	static synchronized String percent(double value)
	{
		return PERCENT.format(value) + "%";
	}

	static synchronized String playedTime(int minutes)
	{
		long safeMinutes = Math.max(0, minutes);
		long days = safeMinutes / (24 * 60);
		long hours = (safeMinutes % (24 * 60)) / 60;
		long remainingMinutes = safeMinutes % 60;
		if (days > 0)
		{
			return INTEGER.format(days) + "d " + hours + "h " + String.format("%02dm", remainingMinutes);
		}
		return hours + "h " + String.format("%02dm", remainingMinutes);
	}

	static String timeTillGoal(int xpRemaining, double xpPerHour)
	{
		if (xpRemaining <= 0)
		{
			return "0:00:00";
		}
		if (xpPerHour <= 0 || !Double.isFinite(xpPerHour))
		{
			return "∞";
		}

		double secondsValue = xpRemaining * 3_600D / xpPerHour;
		long totalSeconds = secondsValue >= Long.MAX_VALUE
			? Long.MAX_VALUE
			: Math.max(0, (long) secondsValue);
		long totalHours = totalSeconds / 3_600;
		long minutes = (totalSeconds % 3_600) / 60;
		long seconds = totalSeconds % 60;
		return String.format("%d:%02d:%02d", totalHours, minutes, seconds);
	}

	static String duration(long millis)
	{
		Duration duration = Duration.ofMillis(Math.max(0, millis));
		long hours = duration.toHours();
		long minutes = duration.minusHours(hours).toMinutes();
		long seconds = duration.minusHours(hours).minusMinutes(minutes).getSeconds();
		return String.format("%02d:%02d:%02d", hours, minutes, seconds);
	}
}

