final class RatesPanel extends JPanel
{
	private static final long serialVersionUID = 1L;
	private static final int GAP = 8;
	private final TempleRateRepository repository;
	private final EhpSession session;
	private final EhpCalculator calculator;
	private final CustomRateStore customRateStore;
