	private final Consumer<GameModeSetting> onGameModeChanged;
	private final JLabel source = new JLabel();
	private final JComboBox<GameModeSetting> gameMode = new JComboBox<>(GameModeSetting.values());
	private final JComboBox<Skill> skill = new JComboBox<>(Skill.values());
	private final JLabel currentLevel = new JLabel();
	private final JTextField defaultRate = new JTextField();
	private final JLabel method = new JLabel();
	private final JFormattedTextField customRate;
	private final JLabel customStatus = new JLabel();
	private final Border customRateBorder;
	private TempleGameMode effectiveMode = TempleGameMode.MAIN;
	private TempleGameMode renderedMode;
	private Skill renderedSkill;
	private int renderedXp = -1;
	private double renderedCustomRate = -1;
	private boolean invalidated = true;
	private boolean refreshing;

	RatesPanel(TempleRateRepository repository, EhpSession session, EhpCalculator calculator,
		CustomRateStore customRateStore, SkillIconManager iconManager,
		Consumer<GameModeSetting> onGameModeChanged, Runnable onRateChanged)
	{
		this.repository = repository;
		this.session = session;
		this.calculator = calculator;
		this.customRateStore = customRateStore;
		this.onGameModeChanged = onGameModeChanged;
		this.onRateChanged = onRateChanged;

		setLayout(new BorderLayout());
		setOpaque(false);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);
		content.setBorder(BorderFactory.createEmptyBorder(2, 2, 8, 2));

		addField(content, "Game mode", gameMode);
		source.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		source.setBorder(BorderFactory.createEmptyBorder(1, 1, 5, 1));
		content.add(fullWidth(source));
		content.add(Box.createRigidArea(new Dimension(0, GAP)));

		skill.setRenderer(new SkillRenderer(iconManager));
		skill.setMaximumRowCount(12);
		addField(content, "Skill", skill);
		currentLevel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		currentLevel.setBorder(BorderFactory.createEmptyBorder(1, 1, 5, 1));
		content.add(fullWidth(currentLevel));
		content.add(Box.createRigidArea(new Dimension(0, GAP)));

		defaultRate.setEditable(false);
		defaultRate.setFocusable(false);
		defaultRate.setHorizontalAlignment(SwingConstants.RIGHT);
		defaultRate.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		addField(content, "Default TempleOSRS XP/h", defaultRate);

		JLabel methodHeading = new JLabel("TempleOSRS method");
		methodHeading.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(methodHeading);
		method.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		method.setBorder(BorderFactory.createEmptyBorder(3, 1, 8, 1));
		content.add(fullWidth(method));

		NumberFormat numberFormat = NumberFormat.getIntegerInstance();
		NumberFormatter formatter = new NumberFormatter(numberFormat);
