		formatter.setMinimum(1L);
		formatter.setMaximum(2_000_000_000L);
		formatter.setAllowsInvalid(true);
		formatter.setCommitsOnValidEdit(false);
		customRate = new JFormattedTextField(formatter);
		customRate.setHorizontalAlignment(SwingConstants.RIGHT);
