			if (!refreshing)
			{
				onGameModeChanged.accept((GameModeSetting) gameMode.getSelectedItem());
			}
		});
		skill.addActionListener(event ->
		{
			if (!refreshing)
			{
				invalidated = true;
				refreshSelectedSkill();
			}
		});
		customRate.addActionListener(event -> saveCustomRate());
		customRate.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent event)
			{
				saveCustomRate();
			}
		});
	}

	void refresh(TempleGameMode mode, GameModeSetting configuredMode)
	{
		if (effectiveMode != mode)
		{
			invalidated = true;
		}
		effectiveMode = mode;
		refreshing = true;
		if (gameMode.getSelectedItem() != configuredMode)
		{
			gameMode.setSelectedItem(configuredMode);
		}
		refreshing = false;

		String selection = configuredMode == GameModeSetting.AUTO
			? "Auto-detected: " + mode
			: "Using TempleOSRS: " + mode;
		source.setText("<html>" + selection + "<br>Rates updated "
			+ repository.getLastUpdated(mode) + "</html>");
		limitHeight(source);
		refreshSelectedSkill();
	}

	void invalidateRates()
	{
		invalidated = true;
		refreshSelectedSkill();
	}

	private void refreshSelectedSkill()
	{
		Skill selectedSkill = (Skill) skill.getSelectedItem();
		if (selectedSkill == null)
		{
			return;
		}

		int xp = Math.max(0, session.getCurrentXp(selectedSkill));
		boolean lookupChanged = invalidated || selectedSkill != renderedSkill
			|| effectiveMode != renderedMode || xp != renderedXp;
		if (lookupChanged)
		{
			int level = Experience.getLevelForXp(xp);
			EhpCalculator.RateView temple = calculator.getRateAt(effectiveMode, selectedSkill, xp, 0);
			currentLevel.setText("Current: level " + level + " (" + UiFormat.integer(xp) + " XP)");

			String methodText = temple.getMethod();
			if (methodText == null || methodText.isEmpty())
			{
				methodText = "No method description published";
			}
			if (temple.getRate() > 0)
			{
				defaultRate.setText(UiFormat.integer(temple.getRate()));
				if (!temple.isDirect())
				{
					methodText += " TempleOSRS marks this as bonus or zero-time XP.";
				}
			}
			else
			{
				defaultRate.setText("Not published");
			}
			defaultRate.setToolTipText(methodText);
			method.setText(toHtml(methodText));
			method.setToolTipText(methodText);
			limitHeight(currentLevel);
			limitHeight(method);
		}

		double storedRate = customRateStore.getActiveRate(selectedSkill);
		boolean customChanged = invalidated || selectedSkill != renderedSkill
			|| Double.compare(storedRate, renderedCustomRate) != 0;
		if (customChanged && !customRate.hasFocus())
		{
			refreshing = true;
			customRate.setValue(storedRate > 0 ? Math.round(storedRate) : null);
			customRate.setBorder(customRateBorder);
			customStatus.setText(storedRate > 0
				? "Custom rate active for " + selectedSkill.getName()
				: "Leave blank to use the TempleOSRS rate");
			limitHeight(customStatus);
			refreshing = false;
		}

		renderedSkill = selectedSkill;
		renderedMode = effectiveMode;
		renderedXp = xp;
		renderedCustomRate = storedRate;
		invalidated = false;
		revalidate();
		repaint();
	}

	private void saveCustomRate()
	{
		if (refreshing)
		{
			return;
		}
		Skill selectedSkill = (Skill) skill.getSelectedItem();
		if (selectedSkill == null)
		{
			return;
		}

		String text = customRate.getText().trim();
		if (text.isEmpty())
		{
			customRateStore.reset(selectedSkill);
			onRateChanged.run();
			refreshSelectedSkill();
			return;
		}

		try
		{
			customRate.commitEdit();
			Object value = customRate.getValue();
			double rate = value instanceof Number ? ((Number) value).doubleValue() : 0;
			if (rate <= 0)
			{
				throw new ParseException("Rate must be positive", 0);
			}
			customRateStore.setRate(selectedSkill, rate);
			customRateStore.setEnabled(selectedSkill, true);
			customRate.setBorder(customRateBorder);
			customStatus.setText("Custom rate active for " + selectedSkill.getName());
			limitHeight(customStatus);
			onRateChanged.run();
		}
		catch (ParseException ex)
		{
			Toolkit.getDefaultToolkit().beep();
			customRate.setBorder(BorderFactory.createLineBorder(ColorScheme.PROGRESS_ERROR_COLOR));
			customStatus.setText("Enter a whole number greater than zero");
			limitHeight(customStatus);
		}
	}

	private void resetCustomRate()
	{
		Skill selectedSkill = (Skill) skill.getSelectedItem();
		if (selectedSkill != null)
		{
			customRateStore.reset(selectedSkill);
			onRateChanged.run();
			refreshSelectedSkill();
		}
	}

	private static void addField(JPanel panel, String labelText, JComponent field)
	{
		JLabel label = new JLabel(labelText);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(label);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, field.getPreferredSize().height));
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(field);
		panel.add(Box.createRigidArea(new Dimension(0, GAP)));
	}

	private static JComponent fullWidth(JComponent component)
	{
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		return component;
	}

	private static void limitHeight(JComponent component)
	{
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
	}

	private static String toHtml(String text)
	{
		String safe = text == null ? "" : text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
		return "<html><div style='width:175px'>" + safe + "</div></html>";
	}

	private static final class SkillRenderer extends DefaultListCellRenderer
	{
		private static final long serialVersionUID = 1L;
		private final SkillIconManager iconManager;

		private SkillRenderer(SkillIconManager iconManager)
		{
			this.iconManager = iconManager;
		}

		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index,
			boolean isSelected, boolean cellHasFocus)
		{
			JLabel label = (JLabel) super.getListCellRendererComponent(
				list, value, index, isSelected, cellHasFocus);
			if (value instanceof Skill)
			{
				Skill renderedSkill = (Skill) value;
				label.setText(renderedSkill.getName());
				label.setIcon(new ImageIcon(iconManager.getSkillImage(renderedSkill, true)));
			}
			return label;
		}
	}
}

