package io.github.veganismftw.templeehptracker;

import net.runelite.api.Experience;

final class EhpSkillGoal
{
	private final int startLevel;
	private final int endLevel;
	private final int endXp;
	private final double progress;

	private EhpSkillGoal(int startLevel, int endLevel, int endXp, double progress)
	{
		this.startLevel = startLevel;
		this.endLevel = endLevel;
		this.endXp = endXp;
		this.progress = progress;
	}

	static EhpSkillGoal forXp(int currentXp)
	{
		int xp = Math.max(0, Math.min(currentXp, Experience.MAX_SKILL_XP));
		int level = Experience.getLevelForXp(xp);
		int startXp = Experience.getXpForLevel(level);
		int endLevel;
		int endXp;
		if (level >= Experience.MAX_VIRT_LEVEL)
		{
			endLevel = Experience.MAX_VIRT_LEVEL;
			endXp = Experience.MAX_SKILL_XP;
		}
		else
		{
			endLevel = level + 1;
			endXp = Experience.getXpForLevel(endLevel);
		}

		double progress = endXp <= startXp
			? 100
			: (xp - startXp) * 100D / (endXp - startXp);
		return new EhpSkillGoal(level, endLevel, endXp, Math.max(0, Math.min(100, progress)));
	}

	int getStartLevel()
	{
		return startLevel;
	}

	int getEndLevel()
	{
		return endLevel;
	}

	int getEndXp()
	{
		return endXp;
	}

	double getProgress()
	{
		return progress;
	}

	boolean isMaxGoal()
	{
		return endXp == Experience.MAX_SKILL_XP;
	}
}

