		xpRows.add(xpGained);
		xpRows.add(xpPerHour);
		stats.add(xpRows);
		headerPanel.add(stats, BorderLayout.CENTER);

		JPanel footer = new JPanel();
		footer.setLayout(new javax.swing.BoxLayout(footer, javax.swing.BoxLayout.Y_AXIS));
		footer.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		progressWrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		progressWrapper.setBorder(DEFAULT_PROGRESS_BORDER);
		progressBar.setMaximumValue(100);
		progressBar.setBackground(new Color(61, 56, 49));
		progressBar.setForeground(SkillColor.find(skill).getColor());
		compactSkillIcon = skillIcon(iconManager, skill, 25, 16, true);
		compactSkillIcon.setVisible(false);
		progressWrapper.add(compactSkillIcon, BorderLayout.WEST);
		progressWrapper.add(progressBar, BorderLayout.CENTER);
		footer.add(progressWrapper);

		setSmallFont(activeTime);
		activeTime.setBorder(new EmptyBorder(0, 7, 7, 7));
		activeTime.setAlignmentX(Component.LEFT_ALIGNMENT);
		footer.add(activeTime);

		container.add(headerPanel, BorderLayout.NORTH);
		container.add(footer, BorderLayout.SOUTH);
		add(container, BorderLayout.NORTH);

		JPopupMenu popupMenu = createPopupMenu();
		installPopupMenu(container, popupMenu);
		MouseAdapter compactToggle = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (event.getButton() == MouseEvent.BUTTON1)
				{
					setCompactView(headerPanel.isVisible());
				}
			}
		};
		installClickToggle(container, compactToggle);
	}

	void update(EhpSession.SkillView view, DisplayMode displayMode, boolean showActiveTime)
	{
		this.showActiveTime = showActiveTime;
		ehpGained.setText(htmlLabel("EHP gained", UiFormat.ehp(view.getEhpGained())));
		ehpPerHour.setText(htmlLabel("EHP/h", UiFormat.ehpRate(view.getEhpPerHour())));
		ehpLeft.setText(htmlLabel("EHP left", UiFormat.ehp(view.getEhpLeft())));
		xpGained.setText(htmlLabel("XP gained", UiFormat.integer(view.getXpGained())));
		xpPerHour.setText(htmlLabel("XP/h", UiFormat.integer(view.getXpPerHour())));
		xpRows.setVisible(displayMode == DisplayMode.XP_AND_EHP);
		activeTime.setText(htmlLabel("Active time", UiFormat.duration(view.getActiveMillis())));
		activeTime.setVisible(showActiveTime && headerPanel.isVisible());

		EhpSkillGoal goal = view.getGoal();
		progressBar.setValue((int) goal.getProgress());
		progressBar.setCenterLabel(UiFormat.percent(goal.getProgress()));
		progressBar.setLeftLabel("Lvl. " + goal.getStartLevel());
		progressBar.setRightLabel(goal.isMaxGoal() ? "200M" : "Lvl. " + goal.getEndLevel());
		int xpRemaining = Math.max(0, goal.getEndXp() - view.getCurrentXp());
		String goalTooltip = UiFormat.timeTillGoal(xpRemaining, view.getXpPerHour())
			+ (goal.isMaxGoal() ? " till 200M" : " till goal");
		setToolTipRecursively(container, goalTooltip);
		revalidate();
	}

	private void setCompactView(boolean compact)
	{
		headerPanel.setVisible(!compact);
		compactSkillIcon.setVisible(compact);
		progressWrapper.setBorder(compact ? COMPACT_PROGRESS_BORDER : DEFAULT_PROGRESS_BORDER);
		activeTime.setVisible(showActiveTime && !compact);
		revalidate();
		setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
		Container parent = getParent();
		if (parent != null)
		{
			parent.revalidate();
			parent.repaint();
		}
	}

	private JPopupMenu createPopupMenu()
	{
		JPopupMenu popupMenu = new JPopupMenu();
		popupMenu.setBorder(new EmptyBorder(5, 5, 5, 5));
		popupMenu.add(canvasItem);
		popupMenu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent event)
			{
				canvasItem.setText(plugin.hasOverlay(skill) ? REMOVE_FROM_CANVAS : ADD_TO_CANVAS);
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent event)
			{
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent event)
			{
			}
		});
		canvasItem.addActionListener(event ->
		{
			if (plugin.hasOverlay(skill))
			{
				plugin.removeOverlay(skill);
			}
			else
			{
				plugin.addOverlay(skill);
			}
		});
		return popupMenu;
	}

	private static void installPopupMenu(Component component, JPopupMenu popupMenu)
	{
		if (component instanceof JComponent)
		{
			((JComponent) component).setComponentPopupMenu(popupMenu);
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				installPopupMenu(child, popupMenu);
			}
		}
	}

	private static void installClickToggle(Component component, MouseAdapter listener)
	{
		component.addMouseListener(listener);
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				installClickToggle(child, listener);
			}
		}
	}

	static void setToolTipRecursively(Component component, String toolTip)
	{
		if (component instanceof JComponent)
		{
			((JComponent) component).setToolTipText(toolTip);
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				setToolTipRecursively(child, toolTip);
			}
		}
	}

	private static JLabel skillIcon(SkillIconManager iconManager, Skill skill,
		int width, int height, boolean small)
	{
		JLabel icon = new JLabel(new ImageIcon(iconManager.getSkillImage(skill, small)));
		icon.setPreferredSize(new Dimension(width, height));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		icon.setVerticalAlignment(SwingConstants.CENTER);
		return icon;
	}

	private static void setSmallFont(JLabel label)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
	}

	private static String htmlLabel(String key, String value)
	{
		return String.format(HTML_LABEL, ColorUtil.toHexColor(ColorScheme.LIGHT_GRAY_COLOR), key, value);
	}
}

package io.github.veganismftw.templeehptracker;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;

final class CanvasOverlayLayout
{
	static final int PROGRESS_BAR_MINIMUM_WIDTH = 96;
	private static final int MINIMUM_STATS_WIDTH = 64;
	private static final int COLUMN_GAP = 8;
	private static final int ICON_GAP = 4;
	private static final int HORIZONTAL_BORDERS = 10;

	private CanvasOverlayLayout()
	{
	}

	static int preferredWidth(Graphics2D graphics, int iconWidth, int minimumStatsWidth,
		String... labelValuePairs)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int statsWidth = Math.max(MINIMUM_STATS_WIDTH, minimumStatsWidth);
		for (int i = 0; i + 1 < labelValuePairs.length; i += 2)
		{
			String label = labelValuePairs[i];
			String value = labelValuePairs[i + 1];
			if (label == null || value == null)
			{
				continue;
			}
			statsWidth = Math.max(statsWidth,
				metrics.stringWidth(label + ":") + COLUMN_GAP + metrics.stringWidth(value));
		}
		return HORIZONTAL_BORDERS + statsWidth + (iconWidth > 0 ? iconWidth + ICON_GAP : 0);
	}

	static Dimension resizeUserWidth(Dimension current, int previousLayoutWidth,
		int layoutWidth)
	{
		if (current == null)
		{
			return null;
		}
		int adjustedWidth = current.width + layoutWidth - previousLayoutWidth;
		return new Dimension(Math.max(layoutWidth, adjustedWidth), current.height);
	}
}

package io.github.veganismftw.templeehptracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.Skill;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.SkillColor;
import net.runelite.client.ui.overlay.OverlayPanel;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;

final class EhpInfoBoxOverlay extends OverlayPanel
{
	private static final int BORDER_SIZE = 2;
	private static final Rectangle HEADER_BORDER = new Rectangle(2, 1, 4, 0);
	private final TempleEhpPlugin plugin;
	private final CanvasOverlaySettings settings;
	private final Skill skill;
	private final BufferedImage icon;
	private final PanelComponent header = new PanelComponent();
	private final PanelComponent stats = new PanelComponent();
	private int previousLayoutWidth = -1;

	EhpInfoBoxOverlay(TempleEhpPlugin plugin, CanvasOverlaySettings settings,
		Skill skill, BufferedImage icon)
	{
		super(plugin);
		this.plugin = plugin;
		this.settings = settings;
		this.skill = skill;
		this.icon = icon;

		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, 2));
		header.setBorder(HEADER_BORDER);
		header.setBackgroundColor(null);
		stats.setBorder(new Rectangle());
		stats.setGap(new Point(0, 0));
		stats.setOrientation(ComponentOrientation.VERTICAL);
		stats.setBackgroundColor(null);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "EHP Tracker overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		EhpSession.SkillView view = plugin.getSkillView(skill);
		if (view == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		header.getChildren().clear();
		stats.getChildren().clear();
		CanvasMetric primary = settings.getPrimary();
		CanvasSecondaryMetric secondarySetting = settings.getSecondary();
		CanvasMetric secondary = secondarySetting == null ? null : secondarySetting.getMetric();
		String primaryValue = primary.format(view);
		String secondaryValue = secondary == null ? null : secondary.format(view);
		stats.getChildren().add(line(primary.getLabel(), primaryValue));
		if (secondary != null)
		{
			stats.getChildren().add(line(secondary.getLabel(), secondaryValue));
		}

		boolean showIcon = settings.isShowIcon();
		int minimumStatsWidth = settings.isShowProgress()
			? CanvasOverlayLayout.PROGRESS_BAR_MINIMUM_WIDTH : 0;
		int preferredWidth = CanvasOverlayLayout.preferredWidth(
			graphics,
			showIcon ? icon.getWidth() : 0,
			minimumStatsWidth,
			primary.getLabel(), primaryValue,
			secondary == null ? null : secondary.getLabel(), secondaryValue,
			settings.isShowActiveTime() ? "Active time" : null,
			settings.isShowActiveTime() ? UiFormat.duration(view.getActiveMillis()) : null);
		updatePreferredWidth(preferredWidth);

		if (showIcon)
		{
			header.getChildren().add(SplitComponent.builder()
				.first(new ImageComponent(icon))
				.second(stats)
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(new Point(4, 0))
				.build());
		}
		else
		{
			header.getChildren().add(stats);
		}

		panelComponent.getChildren().add(header);
		if (settings.isShowProgress())
		{
			EhpSkillGoal goal = view.getGoal();
			ProgressBarComponent progress = new ProgressBarComponent();
			progress.setMinimum(0);
			progress.setMaximum(100);
			progress.setValue(goal.getProgress());
			// Avoid prepending RuneLite's built-in one-decimal percentage to our label.
			progress.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
			progress.setBackgroundColor(new Color(61, 56, 49));
			progress.setForegroundColor(SkillColor.find(skill).getColor());
			progress.setLeftLabel(String.valueOf(goal.getStartLevel()));
			progress.setCenterLabel(UiFormat.percent(goal.getProgress()));
			progress.setRightLabel(goal.isMaxGoal() ? "200M" : String.valueOf(goal.getEndLevel()));
			panelComponent.getChildren().add(progress);
		}
		if (settings.isShowActiveTime())
		{
			panelComponent.getChildren().add(line("Active time", UiFormat.duration(view.getActiveMillis())));
		}
		return super.render(graphics);
	}

	Skill getSkill()
	{
		return skill;
	}

	@Override
	public String getName()
	{
		return super.getName() + " " + skill.getName();
	}

	private static LineComponent line(String label, String value)
	{
		return LineComponent.builder()
			.left(label + ":")
			.right(value)
			.build();
	}

	private void updatePreferredWidth(int width)
	{
		if (previousLayoutWidth >= 0 && previousLayoutWidth != width)
		{
			Dimension resized = CanvasOverlayLayout.resizeUserWidth(
				getPreferredSize(), previousLayoutWidth, width);
			if (resized != null)
			{
				setPreferredSize(resized);
			}
		}
		previousLayoutWidth = width;
		panelComponent.setPreferredSize(new Dimension(width, 0));
	}
}

package io.github.veganismftw.templeehptracker;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
final class TempleRateRepository
{
	private final TempleRateSnapshot snapshot;

	@Inject
	TempleRateRepository(Gson gson)
	{
		try (InputStream stream = TempleRateRepository.class.getResourceAsStream("/temple-rates.json"))
		{
			if (stream == null)
			{
				throw new IllegalStateException("Bundled TempleOSRS rate snapshot is missing");
			}
			snapshot = gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8), TempleRateSnapshot.class);
		}
		catch (IOException ex)
		{
			throw new IllegalStateException("Unable to load bundled TempleOSRS rate snapshot", ex);
		}
	}

	Optional<TempleRateSnapshot.SkillRates> getRates(TempleGameMode mode, Skill skill)
	{
		TempleRateSnapshot.ModeRates modeRates = snapshot.getModes().get(mode.name());
		if (modeRates == null)
		{
			return Optional.empty();
		}
		return Optional.ofNullable(modeRates.getSkills().get(skill.name()));
	}

	String getGeneratedDate()
	{
		return snapshot.getGenerated();
	}

	String getLastUpdated(TempleGameMode mode)
	{
		TempleRateSnapshot.ModeRates rates = snapshot.getModes().get(mode.name());
		return rates == null ? "Unknown" : rates.getLastUpdated();
	}

	String getSource()
	{
		return snapshot.getSource();
	}
}

